<?php
$template = $template ?? [];
$version = $version ?? [];
$definition = $version['definition'] ?? ['sections'=>[]];
?>
<div class="page-header d-flex justify-content-between align-items-center mb-4">
    <div>
        <div class="page-title"><?= e($template['name']) ?></div>
        <div class="page-subtitle mb-0">Create a new immutable version. Current version: v<?= (int)($version['version_number'] ?? 0) ?></div>
    </div>
    <a class="btn btn-outline-secondary" href="<?= url('forms/templates/'.$template['slug'].'/versions') ?>">Version history</a>
</div>
<div class="alert alert-info small">Changes made here never modify the current published version. Saving creates a new immutable version. Existing records continue using the version they were created with.</div>
<form method="post" action="<?= url('forms/templates/store') ?>" id="templateEditor">
<input type="hidden" name="_csrf" value="<?= e(Security::csrfToken()) ?>"><input type="hidden" name="slug" value="<?= e($template['slug']) ?>"><input type="hidden" name="definition" id="definition">
<div id="sections"></div>
<div class="mt-3"><button type="button" class="btn btn-outline-primary" id="addSection">+ Add section</button></div>
<div class="card mt-4"><div class="card-body"><label class="form-label">Change summary</label><input class="form-control" name="change_summary" required placeholder="Describe what changed in this version"><div class="mt-3 d-flex justify-content-end"><button class="btn btn-primary">Create new version</button></div></div></div>
</form>
<script>
const state=<?= json_encode($definition,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;state.sections=Array.isArray(state.sections)?state.sections:[];
const root=document.getElementById('sections');
const esc=s=>String(s??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const types=['text','textarea','select','multiselect','client','date','number','email','auto'];
function render(){root.innerHTML='';state.sections.forEach((sec,si)=>{sec.fields=Array.isArray(sec.fields)?sec.fields:[];const box=document.createElement('div');box.className='card mb-4';box.innerHTML=`<div class="card-body"><div class="d-flex gap-2 mb-3 align-items-center"><input class="form-control" value="${esc(sec.title)}" placeholder="Section title" data-sec-title="${si}"><button type="button" class="btn btn-outline-secondary" data-move-sec-up="${si}" ${si===0?'disabled':''}>↑</button><button type="button" class="btn btn-outline-secondary" data-move-sec-down="${si}" ${si===state.sections.length-1?'disabled':''}>↓</button><button type="button" class="btn btn-outline-danger" data-del-sec="${si}">Delete</button></div><input class="form-control mb-3" value="${esc(sec.description||'')}" placeholder="Section description" data-sec-desc="${si}"><div data-fields="${si}"></div><button type="button" class="btn btn-sm btn-outline-primary" data-add-field="${si}">+ Add field</button></div>`;root.appendChild(box);const fields=box.querySelector('[data-fields]');sec.fields.forEach((f,fi)=>{const row=document.createElement('div');row.className='border rounded p-3 mb-2';const roleValue=Array.isArray(f.roles)?f.roles.join(', '):'';const optionValue=Array.isArray(f.options)?f.options.join(', '):'';const typeOptions=types.map(t=>`<option value="${t}" ${f.type===t?'selected':''}>${t}</option>`).join('');row.innerHTML=`<div class="row g-2 align-items-start"><div class="col-md-2"><label class="form-text">Key</label><input class="form-control" value="${esc(f.key)}" placeholder="Field key"></div><div class="col-md-3"><label class="form-text">Label</label><input class="form-control" value="${esc(f.label)}" placeholder="Label"></div><div class="col-md-2"><label class="form-text">Type</label><select class="form-select">${typeOptions}</select></div><div class="col-md-3"><label class="form-text">Options</label><input class="form-control" value="${esc(optionValue)}" placeholder="Comma-separated options"></div><div class="col-md-2"><label class="form-text">Roles</label><input class="form-control" value="${esc(roleValue)}" placeholder="controller, processor"></div><div class="col-12 d-flex gap-3 align-items-center mt-2"><div class="form-check"><input class="form-check-input" type="checkbox" ${f.required?'checked':''}><label class="form-check-label">Required</label></div><button type="button" class="btn btn-sm btn-outline-secondary" data-move-field-up="${si}:${fi}" ${fi===0?'disabled':''}>↑</button><button type="button" class="btn btn-sm btn-outline-secondary" data-move-field-down="${si}:${fi}" ${fi===sec.fields.length-1?'disabled':''}>↓</button><button type="button" class="btn btn-sm btn-outline-secondary" data-duplicate-field="${si}:${fi}">Duplicate</button><button type="button" class="btn btn-sm btn-outline-danger" data-del-field="${si}:${fi}">Delete</button></div></div>`;fields.appendChild(row);const inputs=row.querySelectorAll('input');const select=row.querySelector('select');const sync=()=>{f.key=inputs[0].value.trim();f.label=inputs[1].value;f.type=select.value;f.options=inputs[2].value.split(',').map(x=>x.trim()).filter(Boolean);const roles=inputs[3].value.split(',').map(x=>x.trim()).filter(Boolean);if(roles.length)f.roles=roles;else delete f.roles;f.required=inputs[4].checked;};inputs.forEach(el=>el.addEventListener('input',sync));select.addEventListener('change',sync);});});}
root.addEventListener('click',e=>{const t=e.target;if(t.dataset.delSec!==undefined){if(!confirm('Delete this entire section and all its fields?'))return;state.sections.splice(+t.dataset.delSec,1);render();return;}if(t.dataset.moveSecUp!==undefined){const i=+t.dataset.moveSecUp;if(i>0)[state.sections[i-1],state.sections[i]]=[state.sections[i],state.sections[i-1]];render();return;}if(t.dataset.moveSecDown!==undefined){const i=+t.dataset.moveSecDown;if(i<state.sections.length-1)[state.sections[i],state.sections[i+1]]=[state.sections[i+1],state.sections[i]];render();return;}if(t.dataset.addField!==undefined){const s=state.sections[+t.dataset.addField];s.fields??=[];s.fields.push({key:'new_field',label:'New field',type:'text',required:false});render();return;}if(t.dataset.delField!==undefined){const[s,f]=t.dataset.delField.split(':').map(Number);if(!confirm('Delete this field from the new version?'))return;state.sections[s].fields.splice(f,1);render();return;}if(t.dataset.duplicateField!==undefined){const[s,f]=t.dataset.duplicateField.split(':').map(Number);const copy=JSON.parse(JSON.stringify(state.sections[s].fields[f]));copy.key=(copy.key||'field')+'_copy';copy.label=(copy.label||'Field')+' (Copy)';state.sections[s].fields.splice(f+1,0,copy);render();return;}if(t.dataset.moveFieldUp!==undefined){const[s,f]=t.dataset.moveFieldUp.split(':').map(Number);if(f>0)[state.sections[s].fields[f-1],state.sections[s].fields[f]]=[state.sections[s].fields[f],state.sections[s].fields[f-1]];render();return;}if(t.dataset.moveFieldDown!==undefined){const[s,f]=t.dataset.moveFieldDown.split(':').map(Number);if(f<state.sections[s].fields.length-1)[state.sections[s].fields[f],state.sections[s].fields[f+1]]=[state.sections[s].fields[f+1],state.sections[s].fields[f]];render();return;}});
document.getElementById('addSection').onclick=()=>{state.sections.push({title:'New section',description:'',fields:[]});render();};
document.getElementById('templateEditor').onsubmit=()=>{state.sections.forEach((s,si)=>{const box=root.children[si];if(box){s.title=box.querySelector('[data-sec-title]')?.value||s.title;s.description=box.querySelector('[data-sec-desc]')?.value||'';}});document.getElementById('definition').value=JSON.stringify(state);};render();
</script>
